"""Release lifetime and flow-epoch replay.

Installs are atomic: a failed attempt leaves the current release and every
resident bank untouched.  A bank is resident while it is current or pinned by
at least one open epoch, and each release id occupies exactly one bank.
Classified epochs keep their pin until close, and every open must close inside
the request.
"""
from formats import InvalidRequest

PADDING = 1514


class Flow:
    __slots__ = ('active', 'release', 'epoch', 'features', 'last', 'done', 'source')

    def __init__(self, release, epoch):
        self.active = True
        self.release = release
        self.epoch = epoch
        self.features = []
        self.last = None
        self.done = False
        self.source = None


class Engine:
    def __init__(self, models, capacity):
        self.models = models
        self.capacity = capacity
        self.current = None
        self.resident = set()
        self.refs = {}
        self.flows = {}
        self.epochs = {}
        self.installs = []
        self.decisions = []

    # -- pool bookkeeping ---------------------------------------------------
    def usage_of(self, members):
        used_range = 0
        used_exact = 0
        for mid in members:
            model = self.models[mid]
            if model['mode'] == 'range':
                used_range += model['entries']
            else:
                used_exact += model['entries']
        return {'range': used_range, 'exact': used_exact}

    def usage(self):
        return self.usage_of(self.resident)

    def releasable(self, mid):
        return mid is not None and mid != self.current and self.refs.get(mid, 0) == 0

    # -- operations ---------------------------------------------------------
    def install(self, mid, at):
        model = self.models[mid]
        mode = model['mode']
        pool = 'range' if mode == 'range' else 'exact'
        entries = model['entries']
        previous = self.current
        evict = previous if self.releasable(previous) else None
        status = 'ok'
        if entries > self.capacity[pool]:
            status = 'oversize'
        else:
            prospective = set(self.resident)
            if evict is not None:
                prospective.discard(evict)
            prospective.add(mid)
            used = self.usage_of(prospective)
            if used['range'] > self.capacity['range'] or used['exact'] > self.capacity['exact']:
                status = 'busy'
        if status == 'ok':
            if evict is not None:
                self.resident.discard(evict)
            self.resident.add(mid)
            self.current = mid
        self.installs.append({'at': at, 'id': mid, 'status': status,
                              'resident': sorted(self.resident), 'used': self.usage()})

    def open(self, flow_id, at):
        if self.current is None:
            raise InvalidRequest('open without a current release')
        state = self.flows.get(flow_id)
        if state is not None and state.active:
            raise InvalidRequest('reopen of an active flow')
        epoch = self.epochs.get(flow_id, 0)
        self.epochs[flow_id] = epoch + 1
        mid = self.current
        self.resident.add(mid)
        self.refs[mid] = self.refs.get(mid, 0) + 1
        self.flows[flow_id] = Flow(mid, epoch)

    def packet(self, flow_id, timestamp, source, length, at):
        state = self.flows.get(flow_id)
        if state is None or not state.active:
            raise InvalidRequest('packet for an inactive flow')
        previous = state.last
        if previous is not None and timestamp < previous:
            raise InvalidRequest('decreasing timestamp inside an epoch')
        state.last = timestamp
        if state.done:
            # Classified: matching and backup are bypassed, the pin remains.
            return
        model = self.models[state.release]
        width = model['width']
        features = state.features
        if previous is not None and len(features) >= width and \
                timestamp - previous > model['idle_us']:
            self.commit(state, flow_id, at, 'idle', len(features))
            return
        if state.source is None:
            state.source = source
            features.append(PADDING + length)
        elif source == state.source:
            features.append(PADDING + length)
        else:
            features.append(PADDING - length)
        table = model['table']
        if not table.empty:
            found = table.best(features)
            if found is not None:
                _, cid, cls, start = found
                state.done = True
                self.decisions.append({'flow': flow_id, 'epoch': state.epoch,
                                       'release': state.release, 'at': at,
                                       'seen': len(features), 'class': cls,
                                       'reason': 'segment', 'rule': cid, 'start': start})
                return
        if len(features) > model['packet_limit']:
            self.commit(state, flow_id, at, 'limit', len(features))

    def commit(self, state, flow_id, at, reason, seen):
        state.done = True
        model = self.models[state.release]
        cls = model['tree'].predict(model['tree'].features(state.features, width := model['width']))
        self.decisions.append({'flow': flow_id, 'epoch': state.epoch,
                               'release': state.release, 'at': at, 'seen': seen,
                               'class': cls, 'reason': reason, 'rule': None,
                               'start': None})

    def close(self, flow_id, at):
        state = self.flows.get(flow_id)
        if state is None or not state.active:
            raise InvalidRequest('close of an inactive flow')
        if not state.done:
            self.commit(state, flow_id, at, 'close', len(state.features))
        mid = state.release
        self.refs[mid] -= 1
        if self.refs[mid] == 0 and self.current != mid:
            self.resident.discard(mid)
        state.active = False

    # -- driver -------------------------------------------------------------
    def run(self, blocks):
        at = 0
        for block in blocks:
            for event in block:
                op = event[0]
                if op == 'packet':
                    self.packet(event[1], event[2], event[3], event[4], at)
                elif op == 'install':
                    self.install(event[1], at)
                elif op == 'open':
                    self.open(event[1], at)
                else:
                    self.close(event[1], at)
                at += 1
        for state in self.flows.values():
            if state.active:
                raise InvalidRequest('flow left open')
        final = {'current': self.current, 'resident': sorted(self.resident),
                 'used': self.usage()}
        return self.installs, self.decisions, final
